// Lectura de hojas para Reportes (← Presentations, «Report Builder»).
// Misma detección que el original: saltea las filas de metadatos que agrega Salesforce
// («Filtered By», «Show:», «As of…», «Generated by…») y busca la fila de encabezados.
// Sin React ni DOM: se puede probar con Node.
import * as XLSX from 'xlsx';

const META_FIRST_ROW = /^(filtered|show:|as of |generated|account record|customer success)/i;
const META_ROW = /filtered|show:|as of |generated by|account record type/i;
const META_LINE = /filtered|show:|as of |generated by/i;

const filled = (c) => c != null && String(c).trim() !== '';

/** Si la hoja ya empieza con encabezados limpios, la devuelve tal cual; si no, null. */
function detectPlainRange(stdRows) {
  if (!stdRows.length) return { headers: [], data: [] };
  const keys = Object.keys(stdRows[0]);
  const firstVals = keys.map((k) => String(stdRows[0][k] ?? ''));
  const hasMeta = firstVals.some((v) => META_FIRST_ROW.test(v.trim()));
  const hasEmptyHeaders = keys.some((k) => k.includes('__EMPTY'));
  if (!hasMeta && !hasEmptyHeaders) return { headers: keys, data: stdRows };
  return null;
}

/** Filas (array de arrays) → { headers, data } buscando la fila de encabezados. */
export function rowsFromMatrix(aoa) {
  let headerRowIdx = -1;
  for (let i = 0; i < Math.min(aoa.length, 15); i++) {
    const row = aoa[i];
    if (!row) continue;
    const nonEmpty = row.filter(filled).length;
    if (nonEmpty >= 3 && !META_ROW.test(row.join(' '))) { headerRowIdx = i; break; }
  }
  if (headerRowIdx === -1) headerRowIdx = 0;
  if (!aoa[headerRowIdx]) return { headers: [], data: [] };

  const headers = Array.from(aoa[headerRowIdx], (h, idx) => (filled(h) ? String(h).trim() : `Col_${idx + 1}`));
  // Columnas finales sin nombre y sin datos: afuera.
  while (headers.length && headers[headers.length - 1].startsWith('Col_')) {
    const last = headers.length - 1;
    const hasData = aoa.slice(headerRowIdx + 1).some((r) => r && filled(r[last]));
    if (hasData) break;
    headers.pop();
  }

  const data = [];
  for (let j = headerRowIdx + 1; j < aoa.length; j++) {
    const r = aoa[j];
    if (!r || !r.some(filled)) continue;
    const obj = {};
    headers.forEach((h, ci) => { obj[h] = r[ci] != null ? String(r[ci]).trim() : ''; });
    data.push(obj);
  }
  return { headers, data };
}

/** Excel (bytes) → una hoja por pestaña: [{ name, headers, data }]. */
export function readWorkbook(bytes, fileName) {
  const wb = XLSX.read(bytes, { type: 'array', cellDates: true });
  const many = wb.SheetNames.length > 1;
  return wb.SheetNames.map((sheetName) => {
    const ws = wb.Sheets[sheetName];
    const name = many ? `${fileName} [${sheetName}]` : fileName;
    const std = XLSX.utils.sheet_to_json(ws, { raw: false, dateNF: 'yyyy-mm-dd' });
    const plain = detectPlainRange(std);
    if (plain) return { name, ...plain };
    const aoa = XLSX.utils.sheet_to_json(ws, { header: 1, raw: false, dateNF: 'yyyy-mm-dd' });
    return { name, ...rowsFromMatrix(aoa) };
  });
}

/** Separador más probable de un texto delimitado (igual que el original). */
export function guessSeparator(txt) {
  if (txt.includes(';') && !txt.includes(',')) return ';';
  if (txt.split(';').length > txt.split(',').length) return ';';
  if (txt.includes('\t')) return '\t';
  return ',';
}

/** CSV / TSV / texto pegado → { headers, data }. */
export function parseDelimited(txt, forceSep) {
  const sep = forceSep || guessSeparator(txt);
  const lines = txt.replace(/\r/g, '').trim().split('\n');
  let start = 0;
  for (let i = 0; i < Math.min(lines.length, 10); i++) {
    const cells = lines[i].trim().split(sep).filter((c) => c.trim());
    if (META_LINE.test(lines[i]) || cells.length <= 1) start = i + 1;
    else break;
  }
  if (start >= lines.length) start = 0;
  const clean = (v) => v.trim().replace(/^"|"$/g, '');
  const headers = lines[start].split(sep).map(clean);
  const data = [];
  for (let j = start + 1; j < lines.length; j++) {
    if (!lines[j].trim()) continue;
    const vals = lines[j].split(sep).map(clean);
    const obj = {};
    headers.forEach((h, ci) => { obj[h] = vals[ci] || ''; });
    data.push(obj);
  }
  return { headers, data };
}

/** JSON (array de objetos, o un objeto) → { headers, data }. */
export function parseJsonRows(parsed) {
  const arr = Array.isArray(parsed) ? parsed : [parsed];
  if (!arr.length) throw new Error('El JSON está vacío.');
  return { headers: Object.keys(arr[0]), data: arr };
}

/** Texto pegado: si parece JSON lo lee como JSON; si no, como texto delimitado. */
export function parsePasted(txt) {
  const t = txt.trim();
  if (t.startsWith('[') || t.startsWith('{')) {
    try { return parseJsonRows(JSON.parse(t)); } catch { /* no es JSON: sigue como texto */ }
  }
  return parseDelimited(t, null);
}

/** Un archivo cualquiera → [{ name, headers, data }]. */
export async function readSheetsFromFile(file) {
  const ext = file.name.split('.').pop().toLowerCase();
  if (ext === 'json') {
    let parsed;
    try { parsed = JSON.parse(await file.text()); } catch (e) { throw new Error(`${file.name} no es un JSON válido: ${e.message}`); }
    return [{ name: file.name, ...parseJsonRows(parsed) }];
  }
  if (ext === 'csv' || ext === 'tsv' || ext === 'txt') {
    return [{ name: file.name, ...parseDelimited(await file.text(), ext === 'tsv' ? '\t' : null) }];
  }
  return readWorkbook(new Uint8Array(await file.arrayBuffer()), file.name);
}
